70\u91cf\u5316\uff1b**\u6fc0\u6d3b\u4e0e KV \u7f13\u5b58\u5168\u7a0b\u4fdd\u6301 FP16**\u3002\n- \u8fd9\u662f**\u6709\u610f\u7684\u53e3\u5f84\u9009\u62e9**\uff0c\u7528\u4e8e\u9694\u79bb\"RTN vs GPTQ \u5728\u4f4d\u5bbd\u4e0b\u7684\u91cf\u5316\u8d28\u91cf\"\u8fd9\u4e00\u81ea\u53d8\u91cf\uff0c\u907f\u514d\u628a\"\u6fc0\u6d3b/KV \u91cf\u5316\u566a\u58f0\"\u4e0e\"\u6743\u91cd\u4f4d\u5bbd\u6548\u5e94\"\u6df7\u6dc6\u3002QuaRot \u8bba\u6587\u539f\u751f\u91c7\u7528\u7684\"\u6743\u91cd+\u6fc0\u6d3b/KV \u5168\u91cf\u5316\"\u53e3\u5f84\uff08\u542b 4-bit KV\u30014-bit \u6fc0\u6d3b\uff09**\u8d85\u51fa\u672c\u95ee\u9898\u8303\u56f4**\uff0c\u6545\u4e0d\u91c7\u7528\uff1b\u672c\u8bbe\u8ba1\u53ea\u5728\u6743\u91cd\u7ef4\u5ea6\u68c0\u9a8c QuaRot \u65cb\u8f6c\u7684\u6536\u76ca\u3002\u6b64\u53e3\u5f84\u5728\u7ed3\u8bba\u4e2d\u4e0d\u5f97\u56de\u63a8\u6210 QuaRot \u5168\u91cf\u5316\u7aef\u5230\u7aef\u6027\u80fd\u3002\n\n### 2.1 \u91cf\u5316\u5b9e\u73b0\uff08\u542b INT6 \u673a\u5236\uff0c\u7b2c 3 \u9879\u56fa\u5b9a\u8981\u6c42\uff09\n\n**\u7edf\u4e00\u7684\u5206\u7ec4\u5bf9\u79f0\u6574\u6570\u65b9\u6848\uff08RTN \u4e0e GPTQ \u5171\u7528\uff0c\u4fdd\u8bc1\u53ef\u6bd4\uff09**\uff1a\n- \u5206\u7ec4 size `g = 128`\uff08\u6cbf\u8f93\u5165\u901a\u9053\u65b9\u5411\u6bcf\u7ec4 128 \u4e2a\u6743\u91cd\uff09\uff1b`per-channel=True`\uff08\u6bcf\u8f93\u51fa\u901a\u9053\u4e00\u4e2a scale\uff09\u4e4b\u5916\u7684\u7ec4\u5185\u5c3a\u5ea6\u4e3a `scale = absmax / (2^(b-1) \u2212 1)`\uff0c**\u5bf9\u79f0\u3001\u65e0\u96f6\u70b9\uff08zero-point=0\uff09**\u3002\n- \u91cf\u5316/\u53cd\u91cf\u5316\u5728 **PyTorch \u7eaf\u5f20\u91cf\u7b97\u5b50**\u4e2d\u624b\u5199\u5b9e\u73b0\uff08\u5411\u91cf\u5316\u6309\u7ec4\u8ba1\u7b97 scale \u2192 `round(w/scale)` \u2192 `w_q*scale`\uff09\uff0c**INT6 \u4e0e INT8 \u5747\u4e0d\u4f9d\u8d56 bitsandbytes**\uff08\u5176\u539f\u751f\u4ec5\u652f\u6301 4/8\uff09\uff0c\u91c7\u7528\u540c\u4e00\u6761\u624b\u5199\u5206\u7ec4\u5bf9\u79f0\u8def\u5f84\uff0c\u4ec5 `b \u2208 {4,6,8}` \u4e0d\u540c\u3002\u8fd9\u4fdd\u8bc1 6-bit \u4e0e 4/8-bit \u673a\u5236\u5b8c\u5168\u4e00\u81f4\u3001\u53ef\u590d\u73b0\u3002\n- **RTN**\uff1a\u76f4\u63a5 round-to-nearest\uff0c\u65e0\u9700\u6821\u51c6\u3002\n- **GPTQ**\uff1a\u91c7\u7528 IST-DASLab/gptq \u5b9e\u73b0\uff0c\u56fa\u5b9a `bits \u2208 {4,6,8}`\u3001`groupsize=128`\u3001`sym=True`\u3001`perchannel=True`\u3001`desc_act=True`\uff08\u4e0e QuaRot \u9ed8\u8ba4\u4e00\u81f4\uff09\uff1b\u9010\u5c42\u3001\u7528\u6821\u51c6\u96c6 Hessian \u4e0e\u8bef\u5dee\u8865\u507f\u3002\u540c\u4e00\u4f4d\u5bbd\u4e0b RTN/GPTQ \u7684\u7ec4\u7ed3\u6784\u4e0e\u4f4d\u5bbd\u53e3\u5f84\u5b8c\u5168\u4e00\u81f4\u3002\n\n---\n\n## 3. QuaRot \u9002\u914d\u4e0e\"\u65cb\u8f6c\u6b63\u786e\u6027\u95e8\u63a7\"\uff08\u7b2c 2 \u9879\u56fa\u5b9a\u8981\u6c42\uff09\n\n### 3.1 \u9002\u914d\u6b65\u9aa4\n1. \u4ece `spcl/QuaRot` \u5b98\u4ed3\u83b7\u53d6\u65cb\u8f6c\u63d2\u5165\u903b\u8f91\uff0c\u79fb\u690d\u5230 `modeling_phi3.py`\uff1a\u6b8b\u5dee\u6d41 Hadamard \u65cb\u8f6c\uff08\u5d4c\u5165\u8f93\u51fa\u878d\u5408\u3001QKV/up/gate \u8f93\u5165\u4fa7\u878d\u5408\u6743\u91cd\u3001out_proj \u4e0e lm_head \u9006\u65cb\u8f6c\u3001\u5c42\u5185\u6b8b\u5dee\u65b9\u5411 R4 \u8865\u507f\u5757\uff09\u3001\u6ce8\u610f\u529b QK \u968f\u673a Hadamard\uff08RoPE **\u4e4b\u540e**\u8fd0\u884c\u65f6\u65bd\u52a0\uff09\u3001V/PV \u4fa7 Hadamard\u3002\n2. \u82e5 Phi-3 config \u542b `rope_scaling(longrope)`\uff0c\u6309\u957f rope \u5b9e\u73b0\u6821\u9a8c QK Hadamard \u7684\u63d2\u5165\u4f4d\u7f6e\u4e0e\u8be5 RoPE \u53d8\u4f53\u662f\u5426\u517c\u5bb9\uff08\u89c1 \u00a74 \u6838\u5b9e\u9879\uff09\u3002\n3. **\u65cb\u8f6c\u6b63\u786e\u6027\u95e8\u63a7\uff08\u91cf\u5316\u524d\u7684\u63a5\u53d7\u6807\u51c6\uff09**\uff0c\u5728\u72ec\u7acb\u4e8e\u6821\u51c6\u7684 32 \u6761 C4 \u5e8f\u5217\u4e0a\u6bd4\u8f83\"\u65cb\u8f6c\u540e FP \u6a21\u578b\"\u4e0e\"\u539f\u59cb FP16 \u6a21\u578b\"\uff1a\n   - \u9010 transformer \u5c42\u8f93\u51fa\u4f59\u5f26\u76f8\u4f3c\u5ea6 **\u2265 0.999**\uff1b\n   - \u672b\u7aef NLL \u5dee **\u2264 1e-3**\u3002\n   - **\u82e5\u95e8\u63a7\u5931\u8d25 \u2192 \u76f4\u63a5\u5224\u5b9a QuaRot \u5bf9 Phi-3 \u4e0d\u9002\u914d**\uff0c\u8bb0\u5f55\u9996\u4e2a\u5931\u8d25\u5c42/\u6a21\u5757\uff08\u5982 RoPE/QK \u63d2\u5165\u70b9\u3001tied embedding \u65cb\u8f6c\u3001R4 \u6b8b\u5dee\u8865\u507f\uff09\u4f5c\u4e3a\"\u975e\u6cdb\u5316\"\u8bc1\u636e\uff0c\u5e76**\u505c\u6b62**\u8be5\u65cb\u8f6c\u81c2\u7684\u91cf\u5316\u8bc4\u6d4b\uff08\u5728\u62a5\u544a\u4e2d\u4ee5\"adapter failed + \u6545\u969c\u70b9\"\u5448\u73b0\uff0c\u4e0d\u4ea7\u751f\u91cf\u5316\u6570\u503c\uff09\u3002\n   - \u95e8\u63a7\u901a\u8fc7 \u2192 \u7ee7\u7eed\u91cf\u5316\uff1b\u91cf\u5316\u566a\u58f0\u9020\u6210\u7684\u6570\u503c\u5dee\u5f02\u4e0e\u95e8\u63a7\u5dee\u5f02\u4e25\u683c\u533a\u5206\u5f00\u3002\n\n### 3.2 \u67b6\u6784\u6838\u5b9e\u6e05\u5355\uff08\u7b2c 3 \u9879\u56fa\u5b9a\u8981\u6c42\uff0c\u4ee5\u4e0b\u8f7d\u5230\u7684 HF config \u4e3a\u51c6\uff09\n\u8fd0\u884c\u65f6\u4ece `microsoft/Phi-3-mini-4k-instruct/config.json` \u4e0e `modeling_phi3.py` \u9010\u4e00\u6838\u5b9e\u5e76\u5199\u5165\u62a5\u544a\uff1a\n- `num_key_value_heads`\uff08GQA \u5934\u6570\uff0c\u7591\u4e3a 4\uff09\uff1b\n- `tie_word_embeddings`\uff08\u7591\u4e3a true\uff0c\u5f71\u54cd\u5d4c\u5165/lm_head \u8054\u52a8\u65cb\u8f6c\uff09\uff1b\n- \u6fc0\u6d3b\u51fd\u6570\uff08silu vs gelu\uff09\uff1b\n- \u662f\u5426\u5b58\u5728 `rope_scaling`\uff08\u5982 `longrope`\uff0c128k \u53d8\u4f53\u5fc5\u6709\uff0c4k \u53d8\u4f53\u5f85\u6838\u5b9e\uff09\uff1b\n- \u9644\u5e26\uff1a`hidden_size=3072`\u3001`intermediate_size=8192`\u3001`num_hidden_layers=32`\u3001`num_attention_heads=32`\u3001`head_dim`\u3001`rms_norm_eps`\u3001\u5168\u8fde\u63a5\u65e0 bias\u3002\n\n---\n\n## 4. \u8bc4\u6d4b\u534f\u8bae\n\n- **\u56f0\u60d1\u5ea6**\uff1aWikiText-2 test\uff08tokenized\uff0cseqlen=2048\uff0cstride=2048\uff09\uff1bC4 held-out\uff08\u4ece C4 train \u53d6\u4e0e\u6821\u51c6**\u4e0d\u76f8\u4ea4**\u7684 1000 \u6761 \u00d7 2048 tokens\uff0cstride=2048\uff09\u3002\n- **\u96f6\u6837\u672c\u51c6\u786e\u7387**\uff1alm-eval-harness\uff080.4.x\uff0c\u786e\u5b9a\u6027 seed\uff090-shot\uff0c\u4efb\u52a1 = **HellaSwag\u3001ARC-easy\u3001ARC-challenge\u3001WinoGrande\u3001PIQA\u3001OpenbookQA**\uff1binstruct \u6a21\u578b\u6309\u666e\u901a\u8865\u5168\u8bc4\u6d4b\uff0c**\u4e0d\u52a0\u5bf9\u8bdd\u6a21\u677f**\uff08\u53e3\u5f84\u7edf\u4e00\uff0c\u907f\u514d\u6a21\u677f\u5f15\u5165\u989d\u5916\u65b9\u5dee\uff09\u3002\n- **\u6821\u51c6\u96c6\uff08GPTQ\uff09**\uff1aC4\uff08`allenai/c4`\uff0cEnglish\uff09subset **128 \u6761 \u00d7 2048 tokens**\uff0c\u6309\u91cf\u5316\u79cd\u5b50\u56fa\u5b9a\u5207\u5206\uff08seed 0/1/42 \u5bf9\u5e94\u4e0d\u540c\u504f\u79fb\u5757\uff09\u3002\n- **\u968f\u673a\u6027\u4e0e\u6279\u6b21**\uff1atorch/numpy/\u6821\u51c6\u5e8f\u5217\u987a\u5e8f\u5747\u56fa\u5b9a\uff1bGPTQ \u6821\u51c6\u524d\u5411 batch=1\uff08seqlen 2048\uff09\uff1bPPL \u8bc4\u6d4b batch\u22644\uff1blm-eval `--batch_size auto`\u3002\u91cf\u5316\u79cd\u5b50 3 \u4e2a\uff080,1,42\uff09\u3002\n\n---\n\n## 5. \u914d\u7f6e\u8868\uff0813 \u4e2a\uff0c\u7b2c 5 \u9879\u56fa\u5b9a\u8981\u6c42\u7684\u5206\u6790\u57fa\u7840\uff09\n\n| # | \u914d\u7f6e | \u65cb\u8f6c | \u4f4d\u5bbd | \u8bf4\u660e |\n|---|---|---:|---:|---|\n| 1 | FP16 | \u2014 | 16 | \u5929\u82b1\u677f\u53c2\u8003 |\n| 2\u20134 | RTN-4/6/8 | \u65e0 | 4/6/8 | \u65e0\u65cb\u8f6c\u81c2\uff08\u9694\u79bb\u65cb\u8f6c\u6536\u76ca\uff09 |\n| 5\u20137 | GPTQ-4/6/8 | \u65e0 | 4/6/8 | \u65e0\u65cb\u8f6c\u81c2 |\n| 8\u201310 | **QuaRot+RTN-4/6/8** | \u6709 | 4/6/8 | \u4e3b\u81c2\uff08setup_8\uff09 |\n| 11\u201313 | **QuaRot+GPTQ-4/6/8** | \u6709 | 4/6/8 | \u4e3b\u81c2\uff08setup_11\uff09 |\n\n\u6bcf\u4e2a\u91cf\u5316\u914d\u7f6e\u00d73 \u4e2a\u91cf\u5316\u79cd\u5b50\uff1b\u65cb\u8f6c\u6570\u503c\u95e8\u63a7\u53ea\u505a\u4e00\u6b21\uff08\u786e\u5b9a\u6027\u64cd\u4f5c\uff09\u3002\u82e5\u95e8\u63a7\u5931\u8d25\uff0c\u4ec5\u62a5\u544a\u6545\u969c\u70b9\uff08\u00a73.1\uff09\u3002\n\n---\n\n## 6. \u6307\u6807\u4e0e \u0394 \u5b9a\u4e49\uff08\u7b2c 5 \u9879\u56fa\u5b9a\u8981\u6c42\uff09\n\n- `PPL(c)`\uff1atokenized \u56f0\u60d1\u5ea6\uff08WikiText-2 \u4e0e C4 \u5206\u5f00\uff09\u3002\n- `acc(c)`\uff1a\u6bcf\u4efb\u52a1\u51c6\u786e\u7387\u53ca 6 \u4efb\u52a1\u5747\u503c `mean_acc(c)`\u3002\n- `\u0394PPL_c(c) = PPL(c) \u2212 PPL(FP16)`\uff08\u53e6\u62a5\u76f8\u5bf9\u767e\u5206\u6bd4 `(PPL(c)\u2212PPL(FP16))/PPL(FP16)`\uff09\u3002\n- `\u0394acc(c) = mean_acc(FP16) \u2212 mean_acc(c)`\u3002\n- \u65cb\u8f6c\u6536\u76ca\uff1a`Rot\u0394PPL(m,b) = PPL(QuaRot+m-b) \u2212 PPL(m-b \u65e0\u65cb\u8f6c)`\uff1b`Rot\u0394acc` \u540c\u7406\uff08**\u6cdb\u5316\u6027\u7684\u6838\u5fc3\u6307\u6807**\uff09\u3002\n- \u65b9\u6cd5\u5bf9\u6bd4\uff1a\u540c\u4e00\u65cb\u8f6c+\u4f4d\u5bbd\u4e0b `PPL(RTN-b) \u2212 PPL(GPTQ-b)` \u7b49\u3002\n- \u6bcf\u7ec4 `mean \u00b1 std`\uff083 \u79cd\u5b50\uff09\uff1blm-eval \u4efb\u52a1\u7ea7\u4e5f\u62a5 3 \u79cd\u5b50\u95f4 std\u3002\n- 13 \u884c \u00d7 (PPL_wiki, PPL_c4, 6\u00d7acc, mean_acc, \u0394PPL, \u0394acc, \u663e\u5b58GB, \u8017\u65f6min) \u6c47\u603b\u8868\u3002\n\n### \u6821\u51c6/\u8bc4\u6d4b\u96c6\u91cd\u53e0\u98ce\u9669\uff08\u660e\u786e\u8bf4\u660e\uff09\n- C4 \u8bc4\u6d4b\u5757\u4e0e GPTQ \u6821\u51c6\u5757\u5728**\u6837\u672c\u7d22\u5f15\u4e0a\u4e0d\u76f8\u4ea4**\uff08\u6821\u51c6\u53d6 seed \u5bf9\u5e94\u5757\u3001\u8bc4\u6d4b\u53d6\u56fa\u5b9a\u504f\u79fb\u5757 [10000:10000+1000]\uff09\uff0c\u5e76\u5c06\u91cd\u53e0\u68c0\u67e5\uff08\u7d22\u5f15\u4ea4\u96c6=\u2205\uff09\u8ba1\u5165\u6821\u9a8c\u811a\u672c\u3002\n- \u6b8b\u4f59\u98ce\u9669\uff1aC4 \u8bc4\u6d4b\u4e0e C4 \u6821\u51c6**\u540c\u5206\u5e03**\uff08\u540c\u6570\u636e\u96c6\u4e24\u6bb5\uff09\uff0c\u53ef\u80fd\u8f7b\u5fae\u9ad8\u4f30\"\u65cb\u8f6c+\u6821\u51c6\"\u5728 C4 \u4e0a\u7684\u8868\u73b0\uff1b\u6545\u4ee5 **WikiText-2\uff08\u5206\u5e03\u5916\uff09\u4e3a\u4e3b\u6307\u6807**\uff0cC4 held-out \u4e3a\u8f85\u52a9\uff0c\u62a5\u544a\u540c\u65f6\u7ed9\u4e24\u8005\u5e76\u8bf4\u660e\u6b64\u98ce\u9669\u3002\n\n---\n\n## 7. \u5206\u6790\u8ba1\u5212\uff08\u7b2c 5 \u9879\u56fa\u5b9a\u8981\u6c42\uff09\n\n1. **\u95e8\u63a7\u62a5\u544a**\uff1a\u65cb\u8f6c\u540e\u9010\u5c42 cosine\u3001NLL \u5dee\uff1b\u901a\u8fc7/\u5931\u8d25\u53ca\u6545\u969c\u70b9\u3002\n2. **\u4e3b\u8868**\uff1a\u00a76 \u6c47\u603b\u8868\uff0813 \u914d\u7f6e \u00d7 3 \u79cd\u5b50\u5747\u503c\u00b1std\uff09\u3002\n3. **\u4f4d\u5bbd\u8d8b\u52bf**\uff1aINT4\u21926\u21928 \u7684 \u0394PPL/\u0394acc \u5355\u8c03\u6027\uff08RTN \u4e0e GPTQ \u5206\u522b\uff09\u3002\n4. **\u65b9\u6cd5\u5bf9\u6bd4**\uff1aQuaRot \u4e0b GPTQ vs RTN \u5728\u5404\u4f4d\u5bbd\u7684\u5dee\u8ddd\u53ca 4-bit \u65f6\u662f\u5426\u663e\u8457\uff08\u79cd\u5b50\u95f4 std \u662f\u5426\u91cd\u53e0\uff09\u3002\n5. **\u65cb\u8f6c\u6536\u76ca**\uff1a`Rot\u0394PPL/Rot\u0394acc`\uff1b\u4e0e Llama-2-7B \u7684 QuaRot \u8bba\u6587\u53d1\u8868\u503c\u5bf9\u6bd4\uff0c**\u663e\u5f0f\u6807\u6ce8\u4e24\u6a21\u578b\u89c4\u6a21\u5dee\uff08~3.8B vs 7B\uff09**\uff0c\u53ea\u4f5c\u5b9a\u6027\u8d8b\u52bf\u5bf9\u7167\uff1bLlama \u5168\u91cf\u91cd\u8dd1\u4e3a\u53ef\u9009\u589e\u5f3a\uff08\u53ef\u52a0\u4e00\u5217\u540c\u534f\u8bae Llama-2-7B \u6570\u503c\uff0c\u6210\u672c\u7ea6 2\u20133\u00d7\uff09\u3002\n6. **\u7ed3\u8bba\u53e3\u5f84**\uff1a\u5206\u522b\u56de\u7b54 G1\u2013G4\uff1b\u660e\u786e weight-only \u53e3\u5f84\u7684\u8fb9\u754c\uff08\u4e0d\u63a8\u53ca QuaRot \u5168\u91cf\u5316\uff09\u3002\n\n---\n\n## 8. \u53ef\u884c\u6027\uff08A100-40GB \u5355\u5361\u9884\u7b97\uff0c\u7b2c 4 \u9879\u56fa\u5b9a\u8981\u6c42\uff09\n\n- \u6a21\u578b\u89c4\u6a21\uff1aPhi-3-mini ~3.8B \u2192 FP16 \u6743\u91cd ~7.6GB\uff1bweight-only \u4e0b\u63a8\u7406\u65f6\u53cd\u91cf\u5316\u56de FP16\uff0c\u6fc0\u6d3b\u4ecd FP16\uff0c**\u6743\u91cd\u9a7b\u7559\u663e\u5b58\u7ea6 8/6/4-bit \u5206\u522b\u4e3a ~3.8/2.9/1.9GB\uff08\u538b\u7f29\uff09+ \u524d\u5411\u6fc0\u6d3b\u5f00\u9500**\uff1bGPTQ \u9010\u5c42\u6821\u51c6\uff08batch1\u00d72048\uff09Hessian \u4e0e\u5c42\u6743\u91cd\u5747\u5728\u5355\u5c42\u89c4\u6a21\uff0cA100-40GB \u5168\u7a0b\u5145\u88d5\u3002\n- \u6bcf\u914d\u7f6e\u8017\u65f6\uff08\u5355\u5361 A100-40GB\uff0c\u4f30\u7b97\u4e0a\u9650\uff09\uff1a\u95e8\u63a7\u4e00\u6b21 ~15min\uff1bRTN \u91cf\u5316 ~5min\uff1bGPTQ \u6821\u51c6 ~40\u201360min\uff1bPPL\uff08Wiki+C4\uff09~20\u201330min\uff1blm-eval 6 \u4efb\u52a1 ~30\u201345min\u3002**\u5355\u914d\u7f6e \u2264 ~2h\uff0c13 \u914d\u7f6e \u00d7 \u6bcf\u914d\u7f6e 3 \u79cd\u5b50\uff08\u91cf\u5316\u79cd\u5b50\u4ec5\u5f71\u54cd\u91cf\u5316\u4e0e PPL/acc \u8bc4\u6d4b\uff0c\u9700\u91cd\u590d\u8bc4\u6d4b\uff09\u5408\u8ba1\u7ea6 1.5\u20132 \u4e2a GPU\u00b7\u65e5**\uff08\u95e8\u63a7\u4e0e\u6821\u51c6\u6570\u636e\u51c6\u5907\u4e0d\u8ba1\u5165\u91cd\u590d\uff09\u3002\n- \u5f53\u524d\u672c\u673a\u73af\u5883\uff08Python 3.14.4\u3001\u65e0 torch\u3001\u65e0 GPU\u3001network disabled\u3001\u65e0\u73b0\u6210\u6e90\u7801/\u6a21\u578b/\u6570\u636e\uff09**\u4e0d\u80fd\u8fd0\u884c**\u672c\u8bbe\u8ba1\uff1b\u6267\u884c\u9700\u5728\u8054\u7f51 + A100-40GB \u7c7b\u73af\u5883\uff0c\u5148\u4e0b\u8f7d\u5e76\u7f13\u5b58\u6a21\u578b\u3001C4/WikiText-2\u3001lm-eval \u6570\u636e\u96c6\u3002**\u672c\u4efb\u52a1\u4ec5\u4ea4\u4ed8\u8bbe\u8ba1\uff0c\u672a\u8fd0\u884c\u4efb\u4f55\u5b9e\u9a8c\u3002**\n\n---\n\n## 9. Rationale\uff08\u8bbe\u8ba1\u7406\u7531\uff09\n- **weight-only**\uff1a\u8ba9\"RTN vs GPTQ \u7684\u4f4d\u5bbd\u6548\u5e94\"\u6210\u4e3a\u552f\u4e00\u91cf\u5316\u81ea\u53d8\u91cf\uff0c\u907f\u514d\u6fc0\u6d3b/KV \u91cf\u5316\u6df7\u6dc6\u4e3b\u5bf9\u6bd4\uff1b\n- **\u6709/\u65e0\u65cb\u8f6c\u53cc\u81c2**\uff1a\u628a\"\u65cb\u8f6c\u662f\u5426\u6b63\u786e\uff08\u6cdb\u5316\u6027\uff09\"\u4e0e\"\u4f4d\u5bbd\u91cf\u5316\u8d28\u91cf\"\u89e3\u8026\uff0c\u524d\u8005\u7531 G1 \u95e8\u63a7\u3001\u540e\u8005\u7531 G2/G3 \u91cf\u5316\u5bf9\u6bd4\u56de\u7b54\uff1b\n- **\u65cb\u8f6c\u6570\u503c\u95e8\u63a7**\uff1a\u82e5\u4e0d\u505a\uff0c\u5219\"\u65cb\u8f6c\u7834\u574f\u6570\u503c\"\u4e0e\"\u91cf\u5316\u52a3\u5316\"\u65e0\u6cd5\u533a\u5206\u2014\u2014\u95e8\u63a7\u662f\u6cdb\u5316\u6027\u5224\u65ad\u7684\u5fc5\u8981\u5185\u90e8\u5bf9\u7167\uff1b\n- **C4 128\u00d72048 \u6821\u51c6 + WikiText-2/C4 \u8bc4\u6d4b**\uff1a\u4e0e QuaRot/GPTQ \u8bba\u6587\u60ef\u4f8b\u4e00\u81f4\uff0c\u624d\u80fd\u4e0e Llama \u5df2\u53d1\u8868\u6570\u5b57\u76f4\u63a5\u5bf9\u7167\uff1b\n- **GPTQ/RTN \u540c\u7ec4\u7ed3\u6784\uff08groupsize=128, sym\uff09**\uff1a\u6d88\u9664\u5b9e\u73b0\u5dee\u5f02\uff0c\u4f7f\u65b9\u6cd5\u95f4\u5bf9\u6bd4\u5f52\u56e0\u4e8e\"\u662f\u5426\u6709 Hessian \u6821\u51c6\u4e0e\u8bef\u5dee\u8865\u507f\"\u3002\n\n## 10. Controls\uff08\u5bf9\u7167\u8bbe\u8ba1\uff09\n- FP16 \u5929\u82b1\u677f\uff08\u4e0a\u9650\u53c2\u8003\uff09\uff1b\n- \u65cb\u8f6c\u6570\u503c\u95e8\u63a7\uff08\u6b63\u786e\u6027\u5185\u90e8\u5bf9\u7167\uff09\uff1b\n- \u65e0\u65cb\u8f6c\u81c2\uff08\u65cb\u8f6c\u6536\u76ca\u5f52\u56e0\uff09\uff1b\n- Llama-2-7B \u5df2\u53d1\u8868 QuaRot \u6570\u503c\u4f5c\u4e3a\u5916\u90e8\u57fa\u51c6\uff08\u53ef\u9009\u540c\u534f\u8bae\u91cd\u8dd1\uff09\uff1b\n- \u65e0\u5bf9\u8bdd\u6a21\u677f\u3001\u56fa\u5b9a\u79cd\u5b50\u3001\u6821\u51c6/\u8bc4\u6d4b C4 \u6bb5\u4e0d\u76f8\u4ea4\u3001\u4e24\u65b9\u6cd5\u540c `groupsize=128/sym` \u53e3\u5f84\u3002", "assumptions": ["\u76ee\u6807\u6267\u884c\u73af\u5883\u4e3a\u8054\u7f51\u3001\u5177\u5907 \u22651 \u5757 A100-40GB\uff08\u6216\u7b49\u6548\u663e\u5b58\uff09\u7684 GPU\uff1b\u672c\u673a\uff08\u65e0 GPU/\u4f9d\u8d56/\u7f51\u7edc\uff09\u4ec5\u7528\u4e8e\u8bbe\u8ba1\uff0c\u4e0d\u8fd0\u884c\u5b9e\u9a8c", "Phi-3-mini-4k-instruct \u7684\u67b6\u6784\u4e8b\u5b9e\uff08num_key_value_heads\u3001tie_word_embeddings\u3001\u6fc0\u6d3b\u51fd\u6570\u3001\u662f\u5426\u542b longrope rope_scaling \u7b49\uff09\u4ee5\u5b9e\u9645\u4e0b\u8f7d\u5230\u7684 HF config \u4e3a\u51c6\uff0c\u8fd0\u884c\u524d\u6838\u5b9e\u5e76\u5199\u5165\u62a5\u544a", "\u6743\u91cd\u4e13\u7528\uff08weight-only\uff09\u91cf\u5316\u534f\u8bae\u662f\u56fa\u5b9a\u